import torch
import torch.nn as nn
import torch.nn.functional as F
import math
import os
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Custom HIP kernels for LayerNorm and GELU
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void layernorm_kernel(const float* input, const float* weight, const float* bias, float* output, int N, int D, float eps) {
    int row = blockIdx.x;
    const float* row_input = input + row * D;
    float* row_output = output + row * D;

    float sum = 0.0f;
    float sum_sq = 0.0f;
    for (int i = 0; i < D; ++i) {
        float val = row_input[i];
        sum += val;
        sum_sq += val * val;
    }

    float mean = sum / D;
    float var = (sum_sq / D) - (mean * mean);
    float inv_std = 1.0f / sqrtf(var + eps);

    for (int i = 0; i < D; ++i) {
        row_output[i] = (row_input[i] - mean) * inv_std * weight[i] + bias[i];
    }
}

torch::Tensor layernorm_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, float eps) {
    auto N = input.size(0) * input.size(1);
    auto D = input.size(2);
    auto output = torch::empty_like(input);
    layernorm_kernel<<<N, 1>>>(input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), N, D, eps);
    return output;
}

__global__ void new_gelu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        output[idx] = 0.5f * x * (1.0f + tanhf(sqrtf(2.0f / M_PI) * (x + 0.044715f * x * x * x)));
    }
}

torch::Tensor new_gelu_hip(torch::Tensor input) {
    auto size = input.numel();
    auto output = torch::empty_like(input);
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    new_gelu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}

"""

custom_kernels = load_inline(
    name="custom_kernels",
    cpp_sources=hip_source,
    functions=["layernorm_hip", "new_gelu_hip"],
    verbose=True,
)

class NewGELU(nn.Module):
    def forward(self, x):
        return custom_kernels.new_gelu_hip(x)

class LayerNormCustom(nn.Module):
    def __init__(self, n_embd, eps=1e-5):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(n_embd))
        self.bias = nn.Parameter(torch.zeros(n_embd))
        self.eps = eps

    def forward(self, x):
        return custom_kernels.layernorm_hip(x, self.weight, self.bias, self.eps)

class CausalSelfAttention(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen))
                                     .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd

    def forward(self, x):
        B, T, C = x.size()
        # Using built-in flash attention if available, otherwise optimized path
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        # PyTorch's scaled_dot_product_attention is very well optimized on ROCm.
        # It handles causal mask and softmax efficiently.
        y = torch.nn.functional.scaled_dot_product_attention(
            q, k, v, 
            attn_mask=None, 
            dropout_p=self.attn_dropout.p if self.training else 0.0, 
            is_causal=True
        )

        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))
        return y

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = LayerNormCustom(n_embd)
        self.attn = CausalSelfAttention(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = LayerNormCustom(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = NewGELU(),
            dropout = nn.Dropout(resid_pdrop),
        ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x))))

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlpf(self.ln_2(x))
        return x

def get_inputs():
    batch_size = 128
    seq_len = 512
    n_embd = 768
    return [torch.rand(batch_size, seq_len, n_embd).cuda()]

def get_init_inputs():
    n_embd = 768
    n_head = 8
    attn_pdrop = 0.0
    resid_pdrop = 0.0
    max_seqlen = 1024
    return [n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen]

import torch
import torch.nn as nn
import torch.nn.functional as F
import math
import os
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# HIP kernel for fused causal attention
# This kernel will handle the q@k, scaling, causal masking, softmax, and attn@v
# for a single head.
# B: batch size, H: number of heads, T: sequence length, D: head size

attention_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>
#include <hip/hip_fp16.h>

__global__ void fused_causal_attention_kernel(
    const float* __restrict__ q, // (B, H, T, D)
    const float* __restrict__ k, // (B, H, T, D)
    const float* __restrict__ v, // (B, H, T, D)
    float* __restrict__ out,      // (B, H, T, D)
    int B, int H, int T, int D,
    float scale)
{
    // Each block handles one head of one batch: (batch, head, row_of_Q)
    int b = blockIdx.x;
    int h = blockIdx.y;
    int t = blockIdx.z; // row of Q

    if (b >= B || h >= H || t >= T) return;

    // Offsets
    int head_offset = (b * H + h) * T * D;
    const float* q_ptr = q + head_offset + t * D;
    const float* k_ptr = k + head_offset;
    const float* v_ptr = v + head_offset;
    float* out_ptr = out + head_offset + t * D;

    // We need to compute:
    // row_att[j] = exp( (q[t] * k[j]) * scale ) for j <= t
    // row_att[j] = 0 for j > t
    // out[t] = sum(row_att[j] * v[j]) / sum(row_att[j])

    // For better performance, we can use a small shared memory buffer or just registers.
    // Given D=96, it's small enough to keep in registers.

    float max_val = -1e20f;

    // We'll store the dot products in a local array (in registers if T is small)
    // But T=512 is a bit large for registers. Let's use a two-pass approach.

    // First pass: find max_val and compute dot products
    // We can use a small buffer in shared memory.
    extern __shared__ float shared_mem[];
    float* dot_products = shared_mem; // T floats

    for (int j = 0; j <= t; ++j) {
        float sum = 0.0f;
        for (int d = 0; d < D; ++d) {
            sum += q_ptr[d] * k_ptr[j * D + d];
        }
        sum *= scale;
        dot_products[j] = sum;
        if (sum > max_val) max_val = sum;
    }

    // Second pass: compute sum of exps
    float exp_sum = 0.0f;
    for (int j = 0; j <= t; ++j) {
        dot_products[j] = expf(dot_products[j] - max_val);
        exp_sum += dot_products[j];
    }

    // Third pass: compute weighted sum of v
    for (int d = 0; d < D; ++d) {
        float out_val = 0.0f;
        for (int j = 0; j <= t; ++j) {
            out_val += dot_products[j] * v_ptr[j * D + d];
        }
        out_ptr[d] = out_val / exp_sum;
    }
}

torch::Tensor fused_causal_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v, float scale) {
    int B = q.size(0);
    int H = q.size(1);
    int T = q.size(2);
    int D = q.size(3);

    auto out = torch::empty_like(q);

    dim3 grid(B, H, T);
    dim3 block(1); // One thread per row for simplicity initially, though not optimal

    // Each block needs T * sizeof(float) shared memory
    size_t shared_mem_size = T * sizeof(float);

    fused_causal_attention_kernel<<<grid, block, shared_mem_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        out.data_ptr<float>(),
        B, H, T, D,
        scale
    );

    return out;
}
"""

attention_lib = load_inline(
    name="attention_lib",
    cpp_sources=attention_kernel_source,
    functions=["fused_causal_attention_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.n_head = n_head
        self.n_embd = n_embd
        self.scale = 1.0 / math.sqrt(n_embd // n_head)

    def forward(self, x):
        B, T, C = x.size()

        # Linear layer and split
        qkv = self.c_attn(x)
        q, k, v = qkv.split(self.n_embd, dim=2)

        # Reshape for multi-head attention
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()

        # Custom fused attention kernel
        y = attention_lib.fused_causal_attention_hip(q, k, v, self.scale)

        # Reshape and project back
        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))
        return y

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

# HIP kernel for fused Residual + LayerNorm + Permute
# Input: attn_output (L, B, D), residual (L, B, D)
# Output: output (B, D, H, W)
# L = H * W
# embed_dim = D
fused_layernorm_residual_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void fused_layernorm_residual_kernel(
    const float* __restrict__ attn_output,
    const float* __restrict__ residual,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int L, int B, int D, int H, int W, float eps) {

    // Each block handles one (batch, seq_len) vector of size D
    // Grid dim: (L, B)
    // Block dim: D (or a power of 2 >= D)

    int l = blockIdx.x;
    int b = blockIdx.y;
    int tid = threadIdx.x;

    if (l >= L || b >= B) return;

    // Load into shared memory for mean and variance calculation
    extern __shared__ float shared_data[];

    float val = 0.0f;
    if (tid < D) {
        int idx = (l * B + b) * D + tid;
        val = attn_output[idx] + residual[idx];
        shared_data[tid] = val;
    } else {
        shared_data[tid] = 0.0f;
    }
    __syncthreads();

    // Compute mean
    // Simple reduction for D=128
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }
    float mean = shared_data[0] / D;
    __syncthreads();

    // Re-load/re-compute val to avoid using shared memory for mean
    if (tid < D) {
        int idx = (l * B + b) * D + tid;
        val = attn_output[idx] + residual[idx];
        shared_data[tid] = (val - mean) * (val - mean);
    } else {
        shared_data[tid] = 0.0f;
    }
    __syncthreads();

    // Compute variance
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }
    float var = shared_data[0] / D;
    float inv_std = 1.0f / sqrtf(var + eps);

    if (tid < D) {
        // Apply LayerNorm: (val - mean) * inv_std * gamma + beta
        float out_val = (val - mean) * inv_std * gamma[tid] + beta[tid];

        // Permute to (B, D, H, W)
        // Original: (l, b, tid) where l = h*W + w
        int w = l % W;
        int h = l / W;
        // Output shape (B, D, H, W)
        // Output index: b * (D*H*W) + tid * (H*W) + h * W + w
        int out_idx = b * (D * H * W) + tid * (H * W) + h * W + w;
        output[out_idx] = out_val;
    }
}

torch::Tensor fused_layernorm_residual(
    torch::Tensor attn_output,
    torch::Tensor residual,
    torch::Tensor gamma,
    torch::Tensor beta,
    int H, int W, float eps) {

    int L = attn_output.size(0);
    int B = attn_output.size(1);
    int D = attn_output.size(2);

    auto output = torch::empty({B, D, H, W}, attn_output.options());

    // Use a power of 2 for block size >= D
    int block_size = 1;
    while (block_size < D) block_size <<= 1;

    dim3 grid(L, B);
    size_t shared_mem_size = block_size * sizeof(float);

    fused_layernorm_residual_kernel<<<grid, block_size, shared_mem_size>>>(
        attn_output.data_ptr<float>(),
        residual.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        L, B, D, H, W, eps);

    return output;
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_layernorm_residual_cpp_source,
    functions=["fused_layernorm_residual"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, embed_dim, num_heads):
        super(ModelNew, self).__init__()
        self.attn = nn.MultiheadAttention(embed_dim, num_heads)
        self.norm = nn.LayerNorm(embed_dim)
        self.embed_dim = embed_dim
        self.num_heads = num_heads

    def forward(self, x):
        B, C, H, W = x.shape
        # (B, C, H, W) -> (B, C, H*W) -> (H*W, B, C)
        x_reshaped = x.view(B, C, H * W).permute(2, 0, 1).contiguous()

        # Self-attention
        attn_output, _ = self.attn(x_reshaped, x_reshaped, x_reshaped)

        # Fused residual, layer norm, and permute back to (B, C, H, W)
        # attn_output: (L, B, D), x_reshaped: (L, B, D)
        # norm.weight: (D,), norm.bias: (D,)
        x = fused_ops.fused_layernorm_residual(
            attn_output,
            x_reshaped,
            self.norm.weight,
            self.norm.bias,
            H, W,
            self.norm.eps
        )
        return x

def get_inputs():
    return [torch.rand(2, 128, 128, 128).cuda()]

def get_init_inputs():
    return [128, 4]

import torch
import torch.nn as nn
import torch.nn.functional as F
import math
import os
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Custom HIP kernels for LayerNorm and GELU
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>
#include <hip/hip_fp16.h>

template <typename T>
__device__ T warp_reduce_sum(T val) {
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

template <typename T>
__device__ T block_reduce_sum(T val) {
    static __shared__ T shared[32];
    int lane = threadIdx.x % warpSize;
    int wid = threadIdx.x / warpSize;
    val = warp_reduce_sum(val);
    if (lane == 0) shared[wid] = val;
    __syncthreads();
    val = (threadIdx.x < blockDim.x / warpSize) ? shared[lane] : 0.0f;
    if (wid == 0) val = warp_reduce_sum(val);
    return val;
}

__global__ void layernorm_kernel_optimized(const float* __restrict__ input, const float* __restrict__ weight, const float* __restrict__ bias, float* __restrict__ output, int D, float eps) {
    int row = blockIdx.x;
    const float* row_input = input + row * D;
    float* row_output = output + row * D;

    float sum = 0.0f;
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        float val = row_input[i];
        sum += val;
        sum_sq += val * val;
    }

    sum = block_reduce_sum(sum);
    sum_sq = block_reduce_sum(sum_sq);

    __shared__ float shared_mean;
    __shared__ float shared_inv_std;
    if (threadIdx.x == 0) {
        shared_mean = sum / D;
        shared_inv_std = 1.0f / sqrtf((sum_sq / D) - (shared_mean * shared_mean) + eps);
    }
    __syncthreads();

    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        output[row * D + i] = (row_input[i] - shared_mean) * shared_inv_std * weight[i] + bias[i];
    }
}

torch::Tensor layernorm_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, float eps) {
    auto N = input.size(0) * input.size(1);
    auto D = input.size(2);
    auto output = torch::empty_like(input);
    const int threads = 256;
    layernorm_kernel_optimized<<<N, threads>>>(input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), D, eps);
    return output;
}

__global__ void new_gelu_kernel_optimized(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        // 0.5 * x * (1.0 + tanh(sqrt(2.0 / pi) * (x + 0.044715 * x^3)))
        float inner = 0.7978845608f * (x + 0.044715f * x * x * x);
        output[idx] = 0.5f * x * (1.0f + tanhf(inner));
    }
}

torch::Tensor new_gelu_hip(torch::Tensor input) {
    auto size = input.numel();
    auto output = torch::empty_like(input);
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    new_gelu_kernel_optimized<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}

"""

custom_kernels = load_inline(
    name="custom_kernels_v2",
    cpp_sources=hip_source,
    functions=["layernorm_hip", "new_gelu_hip"],
    verbose=True,
)

class NewGELU(nn.Module):
    def forward(self, x):
        return custom_kernels.new_gelu_hip(x)

class LayerNormCustom(nn.Module):
    def __init__(self, n_embd, eps=1e-5):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(n_embd))
        self.bias = nn.Parameter(torch.zeros(n_embd))
        self.eps = eps

    def forward(self, x):
        return custom_kernels.layernorm_hip(x, self.weight, self.bias, self.eps)

class CausalSelfAttention(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen))
                                     .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd

    def forward(self, x):
        B, T, C = x.size()
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        y = torch.nn.functional.scaled_dot_product_attention(
            q, k, v, 
            attn_mask=None, 
            dropout_p=self.attn_dropout.p if self.training else 0.0, 
            is_causal=True
        )

        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))
        return y

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = LayerNormCustom(n_embd)
        self.attn = CausalSelfAttention(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = LayerNormCustom(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = NewGELU(),
            dropout = nn.Dropout(resid_pdrop),
        ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x))))

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlpf(self.ln_2(x))
        return x

def get_inputs():
    batch_size = 128
    seq_len = 512
    n_embd = 768
    return [torch.rand(batch_size, seq_len, n_embd).cuda()]

