import torch
import torch.nn as nn
import torch.nn.functional as F
import math
import os
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# HIP kernel for fused causal attention
# Each block computes one row of the output: out[b, h, t, :]
# Block size: 128 threads

attention_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

#define WARP_SIZE 64

__device__ __forceinline__ float warpReduceMax(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2)
        val = fmaxf(val, __shfl_xor(val, offset));
    return val;
}

__device__ __forceinline__ float warpReduceSum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2)
        val += __shfl_xor(val, offset);
    return val;
}

__device__ __forceinline__ float blockReduceMax(float val) {
    static __shared__ float shared[WARP_SIZE];
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;

    val = warpReduceMax(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < (blockDim.x / WARP_SIZE)) ? shared[lane] : -1e20f;
    if (wid == 0) val = warpReduceMax(val);

    return val;
}

__device__ __forceinline__ float blockReduceSum(float val) {
    static __shared__ float shared[WARP_SIZE];
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < (blockDim.x / WARP_SIZE)) ? shared[lane] : 0.0f;
    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void fused_causal_attention_kernel(
    const float* __restrict__ q, // (B, H, T, D)
    const float* __restrict__ k, // (B, H, T, D)
    const float* __restrict__ v, // (B, H, T, D)
    float* __restrict__ out,      // (B, H, T, D)
    int B, int H, int T, int D,
    float scale)
{
    int b = blockIdx.x;
    int h = blockIdx.y;
    int t = blockIdx.z; // row of Q

    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // Offsets
    int head_offset = (b * H + h) * T * D;
    const float* q_ptr = q + head_offset + t * D;
    const float* k_base = k + head_offset;
    const float* v_base = v + head_offset;
    float* out_ptr = out + head_offset + t * D;

    // Shared memory for dot products (T)
    extern __shared__ float shared_dot_products[];

    // 1. Compute dot products q[t] * k[j] for j <= t
    float max_val = -1e20f;
    for (int j = tid; j < T; j += num_threads) {
        if (j <= t) {
            float sum = 0.0f;
            for (int d = 0; d < D; ++d) {
                sum += q_ptr[d] * k_base[j * D + d];
            }
            sum *= scale;
            shared_dot_products[j] = sum;
            if (sum > max_val) max_val = sum;
        } else {
            shared_dot_products[j] = -1e20f;
        }
    }

    // 2. Compute max across block
    max_val = blockReduceMax(max_val);
    __syncthreads();

    // 3. Compute sum of exps
    float sum_exp = 0.0f;
    for (int j = tid; j < T; j += num_threads) {
        if (j <= t) {
            shared_dot_products[j] = expf(shared_dot_products[j] - max_val);
            sum_exp += shared_dot_products[j];
        } else {
            shared_dot_products[j] = 0.0f;
        }
    }
    sum_exp = blockReduceSum(sum_exp);
    __syncthreads();

    // 4. Compute weighted sum of v
    for (int d = tid; d < D; d += num_threads) {
        float out_val = 0.0f;
        for (int j = 0; j <= t; ++j) {
            out_val += shared_dot_products[j] * v_base[j * D + d];
        }
        out_ptr[d] = out_val / sum_exp;
    }
}

torch::Tensor fused_causal_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v, float scale) {
    int B = q.size(0);
    int H = q.size(1);
    int T = q.size(2);
    int D = q.size(3);

    auto out = torch::empty_like(q);

    dim3 grid(B, H, T);
    dim3 block(128); // Increased block size
    size_t shared_mem_size = T * sizeof(float);

    fused_causal_attention_kernel<<<grid, block, shared_mem_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        out.data_ptr<float>(),
        B, H, T, D,
        scale
    );

    return out;
}
"""

attention_lib = load_inline(
    name="attention_lib",
    cpp_sources=attention_kernel_source,
    functions=["fused_causal_attention_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.n_head = n_head
        self.n_embd = n_embd
        self.scale = 1.0 / math.sqrt(n_embd // n_head)

    def forward(self, x):
        B, T, C = x.size()

        # Linear layer and split
        qkv = self.c_attn(x)
        q, k, v = qkv.split(self.n_embd, dim=2)

        # Reshape for multi-head attention
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()

        # Custom fused attention kernel
        y = attention_lib.fused_causal_attention_hip(q, k, v, self.scale)

        # Reshape and project back
        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))
        return y

import torch
