import torch
import torch.nn as nn
import torch.nn.functional as F
import math
import os
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Optimized HIP kernels
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

#define WARP_SIZE 64

template <typename T>
__device__ T warp_reduce_sum(T val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

template <typename T>
__device__ T block_reduce_sum(T val) {
    static __shared__ T shared[WARP_SIZE];
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;
    val = warp_reduce_sum(val);
    if (lane == 0) shared[wid] = val;
    __syncthreads();
    val = (threadIdx.x < blockDim.x / WARP_SIZE) ? shared[lane] : 0.0f;
    if (wid == 0) val = warp_reduce_sum(val);
    return val;
}

__global__ void layernorm_kernel_fused(const float* __restrict__ input, const float* __restrict__ weight, const float* __restrict__ bias, float* __restrict__ output, int D, float eps) {
    int row = blockIdx.x;
    const float* row_input = input + row * D;
    float* row_output = output + row * D;

    float sum = 0.0f;
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        float val = row_input[i];
        sum += val;
        sum_sq += val * val;
    }

    sum = block_reduce_sum(sum);
    sum_sq = block_reduce_sum(sum_sq);

    __shared__ float shared_mean;
    __shared__ float shared_inv_std;
    if (threadIdx.x == 0) {
        shared_mean = sum / D;
        shared_inv_std = 1.0f / sqrtf((sum_sq / D) - (shared_mean * shared_mean) + eps);
    }
    __syncthreads();

    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        row_output[i] = (row_input[i] - shared_mean) * shared_inv_std * weight[i] + bias[i];
    }
}

__global__ void add_layernorm_kernel_fused(const float* __restrict__ x, const float* __restrict__ y, const float* __restrict__ weight, const float* __restrict__ bias, float* __restrict__ out_x, float* __restrict__ out_norm, int D, float eps) {
    int row = blockIdx.x;
    const float* row_x = x + row * D;
    const float* row_y = y + row * D;
    float* row_out_x = out_x + row * D;
    float* row_out_norm = out_norm + row * D;

    float sum = 0.0f;
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        float val = row_x[i] + row_y[i];
        row_out_x[i] = val;
        sum += val;
        sum_sq += val * val;
    }

    sum = block_reduce_sum(sum);
    sum_sq = block_reduce_sum(sum_sq);

    __shared__ float shared_mean;
    __shared__ float shared_inv_std;
    if (threadIdx.x == 0) {
        shared_mean = sum / D;
        shared_inv_std = 1.0f / sqrtf((sum_sq / D) - (shared_mean * shared_mean) + eps);
    }
    __syncthreads();

    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        row_out_norm[i] = (row_out_x[i] - shared_mean) * shared_inv_std * weight[i] + bias[i];
    }
}

__global__ void bias_gelu_kernel(const float* __restrict__ input, const float* __restrict__ bias, float* __restrict__ output, int D, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx] + bias[idx % D];
        float inner = 0.7978845608f * (x + 0.044715f * x * x * x);
        output[idx] = 0.5f * x * (1.0f + tanhf(inner));
    }
}

torch::Tensor layernorm_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, float eps) {
    auto N = input.size(0) * input.size(1);
    auto D = input.size(2);
    auto output = torch::empty_like(input);
    layernorm_kernel_fused<<<N, 256>>>(input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), D, eps);
    return output;
}

std::vector<torch::Tensor> add_layernorm_hip(torch::Tensor x, torch::Tensor y, torch::Tensor weight, torch::Tensor bias, float eps) {
    auto N = x.size(0) * x.size(1);
    auto D = x.size(2);
    auto out_x = torch::empty_like(x);
    auto out_norm = torch::empty_like(x);
    add_layernorm_kernel_fused<<<N, 256>>>(x.data_ptr<float>(), y.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), out_x.data_ptr<float>(), out_norm.data_ptr<float>(), D, eps);
    return {out_x, out_norm};
}

torch::Tensor bias_gelu_hip(torch::Tensor input, torch::Tensor bias) {
    auto size = input.numel();
    auto D = bias.size(0);
    auto output = torch::empty_like(input);
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    bias_gelu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), D, size);
    return output;
}
"""

custom_kernels = load_inline(
    name="custom_kernels_v3",
    cpp_sources=hip_source,
    functions=["layernorm_hip", "add_layernorm_hip", "bias_gelu_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = nn.LayerNorm(n_embd)
        self.attn = CausalSelfAttentionNew(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = nn.LayerNorm(n_embd)
        self.mlp = MLPNew(n_embd, resid_pdrop)
        self.n_embd = n_embd

    def forward(self, x):
        ln1_out = custom_kernels.layernorm_hip(x, self.ln_1.weight, self.ln_1.bias, self.ln_1.eps)
        attn_out = self.attn(ln1_out)

        # x = x + attn_out; ln2_out = ln_2(x)
        x, ln2_out = custom_kernels.add_layernorm_hip(x, attn_out, self.ln_2.weight, self.ln_2.bias, self.ln_2.eps)

        mlp_out = self.mlp(ln2_out)
        return x + mlp_out

class CausalSelfAttentionNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout_p = attn_pdrop
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.n_head = n_head
        self.n_embd = n_embd

    def forward(self, x):
        B, T, C = x.size()
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        y = torch.nn.functional.scaled_dot_product_attention(
            q, k, v, attn_mask=None, dropout_p=self.attn_dropout_p if self.training else 0.0, is_causal=True
        )

        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))
        return y

class MLPNew(nn.Module):
    def __init__(self, n_embd, resid_pdrop):
        super().__init__()
        self.c_fc = nn.Linear(n_embd, 4 * n_embd)
        self.c_proj = nn.Linear(4 * n_embd, n_embd)
        self.dropout = nn.Dropout(resid_pdrop)

    def forward(self, x):
        # Fuse bias and GELU
        # x = self.c_fc(x)  # this is x @ weight.T + bias
        # We can do: y = x @ weight.T, then fused_bias_gelu(y, bias)
        y = torch.matmul(x, self.c_fc.weight.t())
        y = custom_kernels.bias_gelu_hip(y, self.c_fc.bias)
        y = self.c_proj(y)
        y = self.dropout(y)
        return y

