hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

#define WARP_SIZE 64

template <typename T>
__device__ T warp_reduce_sum(T val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

template <typename T>
__device__ T block_reduce_sum(T val) {
    static __shared__ T shared[32];
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;
    val = warp_reduce_sum(val);
    if (lane == 0) shared[wid] = val;
    __syncthreads();
    val = (threadIdx.x < blockDim.x / WARP_SIZE) ? shared[lane] : 0.0f;
    if (wid == 0) val = warp_reduce_sum(val);
    return val;
}

__global__ void layernorm_kernel(const float* __restrict__ input, const float* __restrict__ weight, const float* __restrict__ bias, float* __restrict__ output, int N, int D, float eps) {
    int row = blockIdx.x;
    if (row >= N) return;
    const float* row_input = input + row * D;
    float* row_output = output + row * D;

    float sum = 0.0f;
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        float val = row_input[i];
        sum += val;
        sum_sq += val * val;
    }

    sum = block_reduce_sum(sum);
    sum_sq = block_reduce_sum(sum_sq);

    __shared__ float shared_mean;
    __shared__ float shared_inv_std;
    if (threadIdx.x == 0) {
        shared_mean = sum / D;
        shared_inv_std = 1.0f / sqrtf((sum_sq / D) - (shared_mean * shared_mean) + eps);
    }
    __syncthreads();

    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        row_output[i] = (row_input[i] - shared_mean) * shared_inv_std * weight[i] + bias[i];
    }
}

__global__ void add_layernorm_kernel(const float* __restrict__ x, const float* __restrict__ y, const float* __restrict__ weight, const float* __restrict__ bias, float* __restrict__ out_x, float* __restrict__ out_norm, int N, int D, float eps) {
    int row = blockIdx.x;
    if (row >= N) return;
    const float* row_x = x + row * D;
    const float* row_y = y + row * D;
    float* row_out_x = out_x + row * D;
    float* row_out_norm = out_norm + row * D;

    float sum = 0.0f;
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        float val = row_x[i] + row_y[i];
        row_out_x[i] = val;
        sum += val;
        sum_sq += val * val;
    }

    sum = block_reduce_sum(sum);
    sum_sq = block_reduce_sum(sum_sq);

    __shared__ float shared_mean;
    __shared__ float shared_inv_std;
    if (threadIdx.x == 0) {
        shared_mean = sum / D;
        shared_inv_std = 1.0f / sqrtf((sum_sq / D) - (shared_mean * shared_mean) + eps);
    }
    __syncthreads();

    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        row_out_norm[i] = (row_out_x[i] - shared_mean) * shared_inv_std * weight[i] + bias[i];
    }
}

__global__ void bias_gelu_kernel(const float* __restrict__ input, const float* __restrict__ bias, float* __restrict__ output, int D, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx] + bias[idx % D];
        float inner = 0.7978845608f * (x + 0.044715f * x * x * x);
        output[idx] = 0.5f * x * (1.0f + tanhf(inner));
    }
}

torch::Tensor layernorm_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, float eps) {
    auto input_reshaped = input.view({-1, input.size(-1)});
    auto N = input_reshaped.size(0);
    auto D = input_reshaped.size(1);
    auto output = torch::empty_like(input_reshaped);
    layernorm_kernel<<<N, 256>>>(input_reshaped.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), N, D, eps);
    return output.view_as(input);
}

std::vector<torch::Tensor> add_layernorm_hip(torch::Tensor x, torch::Tensor y, torch::Tensor weight, torch::Tensor bias, float eps) {
    auto x_reshaped = x.view({-1, x.size(-1)});
    auto y_reshaped = y.view({-1, y.size(-1)});
    auto N = x_reshaped.size(0);
    auto D = x_reshaped.size(1);
    auto out_x = torch::empty_like(x_reshaped);
    auto out_norm = torch::empty_like(x_reshaped);
    add_layernorm_kernel<<<N, 256>>>(x_reshaped.data_ptr<float>(), y_reshaped.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), out_x.data_ptr<float>(), out_norm.data_ptr<float>(), N, D, eps);
    return {out_x.view_as(x), out_norm.view_as(x)};
}

torch::Tensor bias_gelu_hip(torch::Tensor input, torch::Tensor bias) {
    auto size = input.numel();
    auto D = bias.size(0);
    auto output = torch::empty_like(input);
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    bias_gelu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), D, size);
    return output;
}
"""

custom_kernels = load_inline(
    name="custom_kernels_v4",
    cpp_sources=hip_source,
    functions=["layernorm_hip", "add_layernorm_hip", "bias_gelu_hip"],
