fused_layernorm_residual_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void fused_layernorm_residual_kernel(
    const float* __restrict__ attn_output, // (B, L, C)
    const float* __restrict__ x_original,  // (B, C, H, W)
    const float* __restrict__ gamma,       // (C)
    const float* __restrict__ beta,        // (C)
    float* __restrict__ output,            // (B, C, H, W)
    int B, int L, int C, int H, int W, float eps) {

    int b = blockIdx.x;
    int l = blockIdx.y;
    int tid = threadIdx.x;

    if (b >= B || l >= L) return;

    extern __shared__ float shared_data[];

    float val = 0.0f;
    if (tid < C) {
        int idx_attn = (b * L + l) * C + tid;

        int h = l / W;
        int w = l % W;
        // x_original is (B, C, H, W)
        // index: b * (C*H*W) + tid * (H*W) + h * W + w
        int idx_orig = ((b * C + tid) * H + h) * W + w;

        val = attn_output[idx_attn] + x_original[idx_orig];
        shared_data[tid] = val;
    } else {
        shared_data[tid] = 0.0f;
    }
    __syncthreads();

    // Reduction for mean
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }
    float mean = shared_data[0] / C;
    __syncthreads();

    // Reset shared_data for variance calculation
    if (tid < C) {
        float diff = val - mean;
        shared_data[tid] = diff * diff;
    } else {
        shared_data[tid] = 0.0f;
    }
    __syncthreads();

    // Reduction for variance
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }
    float var = shared_data[0] / C;
    float inv_std = 1.0f / sqrtf(var + eps);

    if (tid < C) {
        float out_val = (val - mean) * inv_std * gamma[tid] + beta[tid];
        int h = l / W;
        int w = l % W;
        // Output (B, C, H, W)
        int out_idx = ((b * C + tid) * H + h) * W + w;
        output[out_idx] = out_val;
    }
}

torch::Tensor fused_layernorm_residual(
    torch::Tensor attn_output,
    torch::Tensor x_original,
    torch::Tensor gamma,
    torch::Tensor beta,
    int H, int W, float eps) {

    int B = attn_output.size(0);
    int L = attn_output.size(1);
    int C = attn_output.size(2);

    auto output = torch::empty({B, C, H, W}, attn_output.options());

    dim3 grid(B, L);
    int block_size = 128;
    size_t shared_mem_size = block_size * sizeof(float);

    fused_layernorm_residual_kernel<<<grid, block_size, shared_mem_size>>>(
        attn_output.data_ptr<float>(),
        x_original.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        B, L, C, H, W, eps);

    return output;
}
"""

